+let realmURL = URL(fileURLWithPath: "/Users/radoniusz/Library/Developer/CoreSimulator/Devices/53CBD69C-E05C-4DAC-9A2C-2504C42CB57F/data/Containers/Data/Application/B4834A56-4709-4E8D-9ED9-30026F3818A1/Library/Caches/@alice:localhost/Aggregations/Aggregations.realm")
