+    fatalError("missing realmWithURL:")
+}
+typealias Fn = @convention(c) (AnyClass, Selector, NSURL) -> Unmanaged<AnyObject>?
+let fn = unsafeBitCast(method_getImplementation(method), to: Fn.self)
+guard let realmObject = fn(realmClass, sel, realmURL as NSURL)?.takeRetainedValue() as? NSObject else {
+    fatalError("could not open realm")
+}
+
+guard let schema = realmObject.value(forKey: "schema") as? NSObject else {
+    fatalError("missing schema")
+}
+
+guard let objectSchemas = schema.value(forKey: "objectSchema") as? [NSObject] else {
+    fatalError("missing objectSchema")
+}
+
+for objectSchema in objectSchemas {
+    let name = objectSchema.value(forKey: "objectName") as? String ?? "?"
+    let className = objectSchema.value(forKey: "className") as? String ?? "?"
+    let props = (objectSchema.value(forKey: "properties") as? [NSObject])?.compactMap { $0.value(forKey: "name") as? String } ?? []
